def MeanHolder (L : LatentLaw) : Prop :=
  ∀ d, ∀ x ∈ Icc (-1 : ℝ) 1, ∀ t ∈ Icc (-1 : ℝ) 1,
    |L.mu d x - L.mu d t| ≤ 2 * |x - t| ^ β -- @realizes mu(full-interval Holder modulus)

