def honestIntervals (β : ℝ) (n : ℕ) (σ : ℝ) : Set (IntervalProc n) := -- @realizes Intervals(uniform honesty)
  {I | ∀ L, Model β σ L →
    (9/10 : ℝ) ≤ (experiment L σ n).real (Causalean.Stat.coverageEvent I.lo I.hi (theta L))}

